import { parse } from 'acorn'

import { buildNamespaceAliases } from './identifier'

// ── Module-scope memo (Phase-1 perf) ───────────────────────────────
//
// Both `prescanReferences` and `resolveBindingUsage` parse user code
// with acorn and walk the AST. They are deterministic in their inputs
// and account for ~5–15ms CPU per `/plugins/execute` call. Repeat
// invocations from the same agent (the common `hrbr exec` pattern
// where a CLI loop runs the same snippet across iterations) hit the
// memo and skip parse + walk entirely.
//
// Cache key is the raw input string. V8 hashes strings internally for
// Map; collision-free, no crypto needed. Bound the memo at
// PRESCAN_MEMO_MAX entries; on overflow drop the oldest insertion-
// order entry (FIFO ≈ LRU under steady traffic). Same pattern as
// `apiKeyCache` in `apps/api/src/middleware/auth.ts`.
const PRESCAN_MEMO_MAX = 200
const RESOLVE_MEMO_MAX = 200
// Worker isolates have a 128MB memory ceiling. Without an entry-size
// cap, 200 × 1MB code blobs in the memo could pin a quarter of the
// budget. Skip memoization for outsized inputs entirely — the caller
// just re-parses on the next call (still correct, just not free).
const MEMO_MAX_ENTRY_BYTES = 16 * 1024
const prescanMemo = new Map<string, PrescanResult>()
const resolveMemo = new Map<string, BindingUsage>()

function memoSet<K, V>(memo: Map<K, V>, key: K, value: V, max: number): void {
  if (typeof key === 'string' && key.length > MEMO_MAX_ENTRY_BYTES) return
  if (memo.size >= max) {
    const oldest = memo.keys().next().value
    if (oldest !== undefined) memo.delete(oldest)
  }
  memo.set(key, value)
}

function resolveMemoKey(
  code: string,
  namespaces: ReadonlyArray<string>,
  sandNamespaces: ReadonlyArray<string>
): string {
  // Sorted joins ensure equivalent namespace sets share a key regardless
  // of order. \u0000 separators are illegal in identifiers so they cannot
  // collide with namespace contents.
  const ns = [...namespaces].sort().join(',')
  const sn = [...sandNamespaces].sort().join(',')
  return `${code}\u0000${ns}\u0000${sn}`
}

/**
 * Test-only hook: drops both memo tables. Production callers should
 * never need this — entries TTL out via FIFO eviction.
 *
 * @testOnly
 */
export function __resetBindingMemos(): void {
  prescanMemo.clear()
  resolveMemo.clear()
}

type ScopeKind = 'program' | 'function' | 'block'

interface Scope {
  readonly kind: ScopeKind
  readonly names: Set<string>
}

export interface BindingUsage {
  readonly namespaces: ReadonlyArray<string>
  readonly aliases: ReadonlyMap<string, ReadonlyArray<string>>
  readonly hrbr: boolean
  readonly orbit: boolean
  readonly secrets: boolean
  readonly sand: boolean
  readonly sandNamespaces: ReadonlyArray<string>
  readonly jobs: boolean
  readonly defineJob: boolean
  readonly deployApp: boolean
  /**
   * True when user code references the `step` global (step.do /
   * step.sleep / step.sleepUntil / step.waitForEvent). Triggers
   * mode=workflow auto-routing if the caller didn't specify mode.
   */
  readonly step: boolean
}

export class ReservedBindingCollisionError extends Error {
  readonly names: ReadonlyArray<string>

  constructor(names: ReadonlyArray<string>) {
    super(
      `Cannot declare Harbor reserved binding${names.length === 1 ? '' : 's'}: ${names.join(', ')}`
    )
    this.name = 'ReservedBindingCollisionError'
    this.names = names
  }
}

type AcornNode = {
  readonly type: string
  readonly [key: string]: unknown
}

function isNode(value: unknown): value is AcornNode {
  return (
    Boolean(value) &&
    typeof value === 'object' &&
    typeof (value as { type?: unknown }).type === 'string'
  )
}

function pushScope(scopes: Scope[], kind: ScopeKind): Scope[] {
  return [...scopes, { kind, names: new Set<string>() }]
}

function currentScope(scopes: Scope[]): Scope {
  return scopes[scopes.length - 1]!
}

function nearestFunctionScope(scopes: Scope[]): Scope {
  for (let i = scopes.length - 1; i >= 0; i -= 1) {
    const scope = scopes[i]!
    if (scope.kind === 'function' || scope.kind === 'program') return scope
  }
  return scopes[0]!
}

function declareName(
  scopes: Scope[],
  name: string,
  hoisted: boolean,
  reservedNames: ReadonlySet<string>,
  conflicts: Set<string>
): void {
  if (!name) return
  if (reservedNames.has(name)) conflicts.add(name)
  const scope = hoisted ? nearestFunctionScope(scopes) : currentScope(scopes)
  scope.names.add(name)
}

function declarePattern(
  scopes: Scope[],
  pattern: unknown,
  reservedNames: ReadonlySet<string>,
  conflicts: Set<string>,
  hoisted = false
): void {
  if (!isNode(pattern)) return

  switch (pattern.type) {
    case 'Identifier':
      declareName(scopes, String(pattern.name), hoisted, reservedNames, conflicts)
      return
    case 'RestElement':
      declarePattern(scopes, pattern.argument, reservedNames, conflicts, hoisted)
      return
    case 'AssignmentPattern':
      declarePattern(scopes, pattern.left, reservedNames, conflicts, hoisted)
      return
    case 'ArrayPattern':
      for (const element of pattern.elements as ReadonlyArray<unknown>) {
        declarePattern(scopes, element, reservedNames, conflicts, hoisted)
      }
      return
    case 'ObjectPattern':
      for (const prop of pattern.properties as ReadonlyArray<unknown>) {
        if (!isNode(prop)) continue
        if (prop.type === 'RestElement') {
          declarePattern(scopes, prop.argument, reservedNames, conflicts, hoisted)
          continue
        }
        declarePattern(scopes, prop.value, reservedNames, conflicts, hoisted)
      }
      return
    default:
      return
  }
}

function predeclareStatements(
  scopes: Scope[],
  statements: ReadonlyArray<unknown>,
  reservedNames: ReadonlySet<string>,
  conflicts: Set<string>
): void {
  for (const statement of statements) {
    if (!isNode(statement)) continue
    switch (statement.type) {
      case 'VariableDeclaration':
        for (const declaration of statement.declarations as ReadonlyArray<unknown>) {
          if (!isNode(declaration) || declaration.type !== 'VariableDeclarator') continue
          declarePattern(scopes, declaration.id, reservedNames, conflicts, statement.kind === 'var')
        }
        break
      case 'FunctionDeclaration':
        if (statement.id) declarePattern(scopes, statement.id, reservedNames, conflicts)
        break
      case 'ClassDeclaration':
        if (statement.id) declarePattern(scopes, statement.id, reservedNames, conflicts)
        break
      default:
        break
    }
  }
}

function isDeclared(scopes: Scope[], name: string): boolean {
  for (let i = scopes.length - 1; i >= 0; i -= 1) {
    if (scopes[i]!.names.has(name)) return true
  }
  return false
}

function visitChildren(
  node: AcornNode,
  scopes: Scope[],
  visit: (child: unknown, nextScopes: Scope[]) => void
): void {
  for (const [key, value] of Object.entries(node)) {
    if (key === 'type' || key === 'start' || key === 'end' || key === 'loc') continue
    if (Array.isArray(value)) {
      for (const item of value) visit(item, scopes)
      continue
    }
    visit(value, scopes)
  }
}

function getStaticMemberPropertyName(node: AcornNode): string | null {
  if (node.computed) {
    const property = node.property
    if (
      isNode(property) &&
      property.type === 'Literal' &&
      typeof (property as { value?: unknown }).value === 'string'
    ) {
      return (property as unknown as { value: string }).value
    }
    return null
  }
  const property = node.property
  if (isNode(property) && property.type === 'Identifier') {
    return String(property.name)
  }
  return null
}

function getSandMemberPropertyName(node: AcornNode, scopes: Scope[]): string | null {
  const object = node.object
  if (!isNode(object) || object.type !== 'Identifier') return null
  const objectName = String(object.name)
  if (objectName !== 'sand' || isDeclared(scopes, objectName)) return null
  return getStaticMemberPropertyName(node)
}

function getHrbrMemberPropertyName(node: AcornNode, scopes: Scope[]): string | null {
  const object = node.object
  if (!isNode(object) || object.type !== 'Identifier') return null
  const objectName = String(object.name)
  if (objectName !== 'hrbr' || isDeclared(scopes, objectName)) return null
  return getStaticMemberPropertyName(node)
}

function isHrbrWorkspacePrimitive(name: string | null): boolean {
  return (
    name === null ||
    name === 'storage' ||
    name === 'cache' ||
    name === 'db' ||
    name === 'tools' ||
    name === 'ai'
  )
}

export interface PrescanResult {
  readonly candidates: ReadonlySet<string>
  readonly hrbr: boolean
  readonly orbit: boolean
  readonly secrets: boolean
  readonly sand: boolean
  readonly jobs: boolean
  readonly defineJob: boolean
  readonly deployApp: boolean
  /**
   * True when user code references the `step` global (step.do /
   * step.sleep / step.sleepUntil / step.waitForEvent). Triggers
   * mode=workflow auto-routing if the caller didn't specify mode.
   */
  readonly step: boolean
  readonly parseFailed: boolean
}

/**
 * Best-effort stripper of JS comments and string/template literals.
 *
 * Replaces stripped regions with same-length whitespace so character
 * positions are preserved. Used only on the acorn parse-failure path
 * in `prescanReferences` to keep word-boundary regex scans from
 * matching reserved-global mentions inside comments or string
 * literals. Intentionally permissive: over-stripping is preferred to
 * false positives.
 */
function stripJsLiterals(code: string): string {
  const out: string[] = []
  const len = code.length
  let i = 0
  while (i < len) {
    const ch = code.charCodeAt(i)
    const next = i + 1 < len ? code.charCodeAt(i + 1) : -1
    // Line comment: // ... \n
    if (ch === 0x2f /* / */ && next === 0x2f /* / */) {
      while (i < len && code.charCodeAt(i) !== 0x0a /* \n */) {
        out.push(' ')
        i += 1
      }
      continue
    }
    // Block comment: /* ... */
    if (ch === 0x2f /* / */ && next === 0x2a /* * */) {
      out.push(' ', ' ')
      i += 2
      while (i < len) {
        if (
          code.charCodeAt(i) === 0x2a /* * */ &&
          i + 1 < len &&
          code.charCodeAt(i + 1) === 0x2f /* / */
        ) {
          out.push(' ', ' ')
          i += 2
          break
        }
        out.push(code[i] === '\n' ? '\n' : ' ')
        i += 1
      }
      continue
    }
    // Double-quoted string
    if (ch === 0x22 /* " */) {
      out.push(' ')
      i += 1
      while (i < len) {
        const c = code.charCodeAt(i)
        if (c === 0x5c /* \ */ && i + 1 < len) {
          out.push(' ', ' ')
          i += 2
          continue
        }
        if (c === 0x22 /* " */) {
          out.push(' ')
          i += 1
          break
        }
        out.push(code[i] === '\n' ? '\n' : ' ')
        i += 1
      }
      continue
    }
    // Single-quoted string
    if (ch === 0x27 /* ' */) {
      out.push(' ')
      i += 1
      while (i < len) {
        const c = code.charCodeAt(i)
        if (c === 0x5c /* \ */ && i + 1 < len) {
          out.push(' ', ' ')
          i += 2
          continue
        }
        if (c === 0x27 /* ' */) {
          out.push(' ')
          i += 1
          break
        }
        out.push(code[i] === '\n' ? '\n' : ' ')
        i += 1
      }
      continue
    }
    // Template literal: replace entire thing (including interpolations)
    // with whitespace. Conservative but acceptable per spec.
    if (ch === 0x60 /* ` */) {
      out.push(' ')
      i += 1
      while (i < len) {
        const c = code.charCodeAt(i)
        if (c === 0x5c /* \ */ && i + 1 < len) {
          out.push(' ', ' ')
          i += 2
          continue
        }
        if (c === 0x60 /* ` */) {
          out.push(' ')
          i += 1
          break
        }
        out.push(code[i] === '\n' ? '\n' : ' ')
        i += 1
      }
      continue
    }
    out.push(code[i]!)
    i += 1
  }
  return out.join('')
}

/**
 * Fast pre-scan over user code to collect free identifier names plus
 * the four reserved bindings (`orbit`, `secrets`, `sand`, `jobs`).
 *
 * Used by `executeWorker` to constrain the upstream `plugin_sources`
 * D1 query to only the candidate namespaces. The proper namespace plan
 * is still recomputed via `planWorkerNamespaceUsage` once the
 * authoritative source list is loaded — this helper is purely a
 * filter to avoid loading every workspace plugin row when the user
 * code only references one or two of them (or none).
 *
 * On parse failure, returns `parseFailed: true` and an empty candidate
 * set; the caller should fall back to the unfiltered query path so
 * that broken code still produces the same compile-time error users
 * see today.
 */
export function prescanReferences(code: string): PrescanResult {
  const memoHit = prescanMemo.get(code)
  if (memoHit) return memoHit

  let ast: AcornNode
  try {
    ast = parse(code, {
      ecmaVersion: 'latest',
      sourceType: 'script',
      allowAwaitOutsideFunction: true,
      allowReturnOutsideFunction: true,
    }) as unknown as AcornNode
  } catch {
    const stripped = stripJsLiterals(code)
    const failed: PrescanResult = {
      candidates: new Set(),
      hrbr: /\bhrbr\s*\.\s*[A-Za-z_$]/.test(stripped),
      orbit: /\borbit\s*\.\s*[A-Za-z_$]/.test(stripped),
      secrets: /\bsecrets\s*\.\s*[A-Za-z_$]/.test(stripped),
      sand: /\bsand\s*\.\s*[A-Za-z_$]/.test(stripped),
      jobs:
        /\bjobs\s*\.\s*[A-Za-z_$]/.test(stripped) ||
        /\bhrbr\s*\.\s*jobs\s*\.\s*[A-Za-z_$]/.test(stripped),
      defineJob: /\bdefineJob\s*\(/.test(stripped),
      deployApp: /\bdeployApp\s*\(/.test(stripped),
      step: /\bstep\s*\.\s*(do|sleep|sleepUntil|waitForEvent)\b/.test(stripped),
      parseFailed: true,
    }
    memoSet(prescanMemo, code, failed, PRESCAN_MEMO_MAX)
    return failed
  }

  let hrbr = false
  let orbit = false
  let secrets = false
  let sand = false
  let jobs = false
  let defineJob = false
  let deployApp = false
  let step = false
  const candidates = new Set<string>()

  const visit = (node: unknown, scopes: Scope[]): void => {
    if (!isNode(node)) return
    switch (node.type) {
      case 'Program':
        predeclareStatements(scopes, node.body as ReadonlyArray<unknown>, new Set(), new Set())
        for (const statement of node.body as ReadonlyArray<unknown>) visit(statement, scopes)
        return
      case 'BlockStatement': {
        const blockScopes = pushScope(scopes, 'block')
        predeclareStatements(blockScopes, node.body as ReadonlyArray<unknown>, new Set(), new Set())
        for (const statement of node.body as ReadonlyArray<unknown>) visit(statement, blockScopes)
        return
      }
      case 'VariableDeclaration':
        for (const declaration of node.declarations as ReadonlyArray<unknown>) {
          if (!isNode(declaration) || declaration.type !== 'VariableDeclarator') continue
          declarePattern(scopes, declaration.id, new Set(), new Set(), node.kind === 'var')
          visit(declaration.init, scopes)
        }
        return
      case 'FunctionDeclaration':
        if (node.id) declarePattern(scopes, node.id, new Set(), new Set(), true)
        {
          const fnScopes = pushScope(scopes, 'function')
          if (node.id) declarePattern(fnScopes, node.id, new Set(), new Set())
          for (const param of node.params as ReadonlyArray<unknown>) {
            declarePattern(fnScopes, param, new Set(), new Set())
          }
          visit(node.body, fnScopes)
        }
        return
      case 'FunctionExpression':
      case 'ArrowFunctionExpression': {
        const fnScopes = pushScope(scopes, 'function')
        if (node.id) declarePattern(fnScopes, node.id, new Set(), new Set())
        for (const param of node.params as ReadonlyArray<unknown>) {
          declarePattern(fnScopes, param, new Set(), new Set())
        }
        visit(node.body, fnScopes)
        return
      }
      case 'ClassDeclaration':
        if (node.id) declarePattern(scopes, node.id, new Set(), new Set(), true)
        visit(node.superClass, scopes)
        visit(node.body, scopes)
        return
      case 'ClassExpression': {
        const classScopes = pushScope(scopes, 'block')
        if (node.id) declarePattern(classScopes, node.id, new Set(), new Set())
        visit(node.superClass, classScopes)
        visit(node.body, classScopes)
        return
      }
      case 'CatchClause': {
        const catchScopes = pushScope(scopes, 'block')
        if (node.param) declarePattern(catchScopes, node.param, new Set(), new Set())
        visit(node.body, catchScopes)
        return
      }
      case 'MemberExpression':
      case 'OptionalMemberExpression': {
        const hrbrPropertyName = getHrbrMemberPropertyName(node, scopes)
        if (hrbrPropertyName) {
          hrbr = true
          if (hrbrPropertyName === 'jobs') jobs = true
          if (isHrbrWorkspacePrimitive(hrbrPropertyName)) orbit = true
        }
        const sandPropertyName = getSandMemberPropertyName(node, scopes)
        if (sandPropertyName) sand = true
        visit(node.object, scopes)
        if (node.computed) visit(node.property, scopes)
        return
      }
      case 'Property':
        if (node.computed) visit(node.key, scopes)
        visit(node.value, scopes)
        return
      case 'MethodDefinition':
      case 'PropertyDefinition':
        if (node.computed) visit(node.key, scopes)
        visit(node.value, scopes)
        return
      case 'LabeledStatement':
        visit(node.body, scopes)
        return
      case 'BreakStatement':
      case 'ContinueStatement':
      case 'DebuggerStatement':
      case 'EmptyStatement':
        return
      case 'Identifier': {
        const name = String(node.name)
        if (isDeclared(scopes, name)) return
        if (name === 'hrbr') hrbr = true
        else if (name === 'orbit') orbit = true
        else if (name === 'secrets') secrets = true
        else if (name === 'sand') sand = true
        else if (name === 'jobs') jobs = true
        else if (name === 'defineJob') defineJob = true
        else if (name === 'deployApp') deployApp = true
        else if (name === 'step') step = true
        else candidates.add(name)
        return
      }
      default:
        visitChildren(node, scopes, visit)
    }
  }

  visit(ast, [{ kind: 'program', names: new Set<string>() }])
  const result: PrescanResult = {
    candidates,
    hrbr,
    orbit,
    secrets,
    sand,
    jobs,
    defineJob,
    deployApp,
    step,
    parseFailed: false,
  }
  memoSet(prescanMemo, code, result, PRESCAN_MEMO_MAX)
  return result
}

export function resolveBindingUsage(
  code: string,
  namespaces: ReadonlyArray<string>,
  sandNamespaces: ReadonlyArray<string> = []
): BindingUsage {
  const memoKey = resolveMemoKey(code, namespaces, sandNamespaces)
  const memoHit = resolveMemo.get(memoKey)
  if (memoHit) return memoHit

  const namespaceAliases = buildNamespaceAliases(namespaces)
  const aliasToNamespace = new Map<string, string>()
  for (const [namespace, aliases] of namespaceAliases) {
    for (const alias of aliases) aliasToNamespace.set(alias, namespace)
  }
  const sandNamespaceAliases = buildNamespaceAliases(sandNamespaces)
  const sandAliasToNamespace = new Map<string, string>()
  for (const [namespace, aliases] of sandNamespaceAliases) {
    sandAliasToNamespace.set(namespace, namespace)
    for (const alias of aliases) sandAliasToNamespace.set(alias, namespace)
  }
  const reservedNames = new Set<string>([
    'hrbr',
    'orbit',
    'sand',
    'secrets',
    'jobs',
    'defineJob',
    'deployApp',
    'step',
    ...aliasToNamespace.keys(),
  ])

  let hrbr = false
  let orbit = false
  let secrets = false
  let sand = false
  let jobs = false
  let defineJob = false
  let deployApp = false
  let step = false
  const referencedNamespaces = new Set<string>()
  const referencedSandNamespaces = new Set<string>()
  const referencedAliasesByNamespace = new Map<string, Set<string>>()
  const reservedBindingConflicts = new Set<string>()

  let ast: AcornNode
  try {
    try {
      ast = parse(code, {
        ecmaVersion: 'latest',
        sourceType: 'script',
        allowAwaitOutsideFunction: true,
        allowReturnOutsideFunction: true,
      }) as unknown as AcornNode
    } catch {
      ast = parse(code, {
        ecmaVersion: 'latest',
        sourceType: 'module',
        allowAwaitOutsideFunction: true,
      }) as unknown as AcornNode
    }
  } catch {
    return {
      namespaces,
      aliases: new Map(
        namespaces.map(
          (namespace) => [namespace, namespaceAliases.get(namespace) ?? [namespace]] as const
        )
      ),
      hrbr: true,
      orbit: true,
      secrets: true,
      sand: true,
      sandNamespaces,
      jobs: true,
      defineJob: true,
      deployApp: true,
      step: true,
    }
  }

  const visit = (node: unknown, scopes: Scope[]): void => {
    if (!isNode(node)) return

    switch (node.type) {
      case 'Program':
        predeclareStatements(
          scopes,
          node.body as ReadonlyArray<unknown>,
          reservedNames,
          reservedBindingConflicts
        )
        for (const statement of node.body as ReadonlyArray<unknown>) visit(statement, scopes)
        return
      case 'BlockStatement': {
        const blockScopes = pushScope(scopes, 'block')
        predeclareStatements(
          blockScopes,
          node.body as ReadonlyArray<unknown>,
          reservedNames,
          reservedBindingConflicts
        )
        for (const statement of node.body as ReadonlyArray<unknown>) visit(statement, blockScopes)
        return
      }
      case 'VariableDeclaration':
        for (const declaration of node.declarations as ReadonlyArray<unknown>) {
          if (!isNode(declaration) || declaration.type !== 'VariableDeclarator') continue
          declarePattern(
            scopes,
            declaration.id,
            reservedNames,
            reservedBindingConflicts,
            node.kind === 'var'
          )
          visit(declaration.init, scopes)
        }
        return
      case 'FunctionDeclaration':
        if (node.id) declarePattern(scopes, node.id, reservedNames, reservedBindingConflicts, true)
        {
          const fnScopes = pushScope(scopes, 'function')
          if (node.id) declarePattern(fnScopes, node.id, reservedNames, reservedBindingConflicts)
          for (const param of node.params as ReadonlyArray<unknown>) {
            declarePattern(fnScopes, param, reservedNames, reservedBindingConflicts)
          }
          visit(node.body, fnScopes)
        }
        return
      case 'FunctionExpression':
      case 'ArrowFunctionExpression': {
        const fnScopes = pushScope(scopes, 'function')
        if (node.id) declarePattern(fnScopes, node.id, reservedNames, reservedBindingConflicts)
        for (const param of node.params as ReadonlyArray<unknown>) {
          declarePattern(fnScopes, param, reservedNames, reservedBindingConflicts)
        }
        visit(node.body, fnScopes)
        return
      }
      case 'ClassDeclaration':
        if (node.id) declarePattern(scopes, node.id, reservedNames, reservedBindingConflicts, true)
        visit(node.superClass, scopes)
        visit(node.body, scopes)
        return
      case 'ClassExpression': {
        const classScopes = pushScope(scopes, 'block')
        if (node.id) declarePattern(classScopes, node.id, reservedNames, reservedBindingConflicts)
        visit(node.superClass, classScopes)
        visit(node.body, classScopes)
        return
      }
      case 'CatchClause': {
        const catchScopes = pushScope(scopes, 'block')
        if (node.param)
          declarePattern(catchScopes, node.param, reservedNames, reservedBindingConflicts)
        visit(node.body, catchScopes)
        return
      }
      case 'MemberExpression':
      case 'OptionalMemberExpression': {
        const hrbrPropertyName = getHrbrMemberPropertyName(node, scopes)
        if (hrbrPropertyName) {
          hrbr = true
          if (hrbrPropertyName === 'jobs') jobs = true
          if (isHrbrWorkspacePrimitive(hrbrPropertyName)) orbit = true
        }
        const sandPropertyName = getSandMemberPropertyName(node, scopes)
        if (sandPropertyName) {
          sand = true
          const namespace = sandAliasToNamespace.get(sandPropertyName)
          if (namespace) referencedSandNamespaces.add(namespace)
        }
        visit(node.object, scopes)
        if (node.computed) visit(node.property, scopes)
        return
      }
      case 'Property':
        if (node.computed) visit(node.key, scopes)
        if (node.shorthand) {
          visit(node.value, scopes)
        } else {
          visit(node.value, scopes)
        }
        return
      case 'MethodDefinition':
      case 'PropertyDefinition':
        if (node.computed) visit(node.key, scopes)
        visit(node.value, scopes)
        return
      case 'LabeledStatement':
        visit(node.body, scopes)
        return
      case 'BreakStatement':
      case 'ContinueStatement':
      case 'DebuggerStatement':
      case 'EmptyStatement':
        return
      case 'Identifier': {
        const name = String(node.name)
        if (name === 'hrbr' && !isDeclared(scopes, name)) {
          hrbr = true
        }
        if (name === 'orbit' && !isDeclared(scopes, name)) {
          orbit = true
        }
        if (name === 'secrets' && !isDeclared(scopes, name)) {
          secrets = true
        }
        if (name === 'sand' && !isDeclared(scopes, name)) {
          sand = true
        }
        if (name === 'jobs' && !isDeclared(scopes, name)) {
          jobs = true
        }
        if (name === 'defineJob' && !isDeclared(scopes, name)) {
          defineJob = true
        }
        if (name === 'deployApp' && !isDeclared(scopes, name)) {
          deployApp = true
        }
        if (name === 'step' && !isDeclared(scopes, name)) {
          step = true
        }
        const namespace = aliasToNamespace.get(name)
        if (namespace && !isDeclared(scopes, name)) {
          referencedNamespaces.add(namespace)
          let aliases = referencedAliasesByNamespace.get(namespace)
          if (!aliases) {
            aliases = new Set<string>()
            referencedAliasesByNamespace.set(namespace, aliases)
          }
          aliases.add(name)
        }
        return
      }
      default:
        visitChildren(node, scopes, visit)
    }
  }

  visit(ast, [{ kind: 'program', names: new Set<string>() }])
  if (reservedBindingConflicts.size > 0) {
    throw new ReservedBindingCollisionError([...reservedBindingConflicts].sort())
  }

  const usedNamespaces = namespaces.filter((namespace) => referencedNamespaces.has(namespace))
  const usedSandNamespaces = sandNamespaces.filter((namespace) =>
    referencedSandNamespaces.has(namespace)
  )
  const result: BindingUsage = {
    namespaces: usedNamespaces,
    aliases: new Map(
      usedNamespaces.map(
        (namespace) =>
          [
            namespace,
            [...(referencedAliasesByNamespace.get(namespace) ?? new Set<string>())],
          ] as const
      )
    ),
    hrbr,
    orbit,
    secrets,
    sand: sand || usedSandNamespaces.length > 0,
    sandNamespaces: usedSandNamespaces,
    jobs,
    defineJob,
    deployApp,
    step,
  }
  memoSet(resolveMemo, memoKey, result, RESOLVE_MEMO_MAX)
  return result
}
