import { resolveBindingUsage, type BindingUsage } from './bindings'

export interface SourceBindingAvailability {
  readonly namespace: string
  readonly kind: 'mcp' | 'api' | 'cli'
  readonly has_cli_bindings: boolean
}

export interface RuntimeNamespaceUsagePlan {
  readonly availableNamespaces: readonly string[]
  readonly availableSandNamespaces: readonly string[]
  readonly namespaces: readonly string[]
  readonly sandNamespaces: readonly string[]
  readonly loadNamespaces: readonly string[]
  readonly hrbr: boolean
  readonly orbit: boolean
  readonly secrets: boolean
  readonly jobs: boolean
  readonly step: boolean
  readonly aliases: BindingUsage['aliases']
}

export function planRuntimeNamespaceUsage(
  userCode: string,
  sources: ReadonlyArray<SourceBindingAvailability>
): RuntimeNamespaceUsagePlan {
  const availableNamespaces = [
    ...new Set(
      sources
        .filter(
          (source) =>
            source.kind === 'mcp' ||
            source.kind === 'api' ||
            (source.kind === 'cli' && source.has_cli_bindings)
        )
        .map((source) => source.namespace)
    ),
  ]
  const availableSandNamespaces = [
    ...new Set(
      sources
        .filter((source) => source.kind === 'cli' && source.has_cli_bindings)
        .map((source) => source.namespace)
    ),
  ]
  const bindingUsage = resolveBindingUsage(userCode, availableNamespaces, availableSandNamespaces)
  const namespaces = [...bindingUsage.namespaces]
  const sandNamespaces = bindingUsage.sand
    ? [
        ...(bindingUsage.sandNamespaces.length > 0
          ? bindingUsage.sandNamespaces
          : availableSandNamespaces),
      ]
    : []
  return {
    availableNamespaces,
    availableSandNamespaces,
    namespaces,
    sandNamespaces,
    loadNamespaces: [...new Set([...namespaces, ...sandNamespaces])],
    hrbr: bindingUsage.hrbr,
    orbit: bindingUsage.orbit,
    secrets: bindingUsage.secrets,
    jobs: bindingUsage.jobs,
    step: bindingUsage.step,
    aliases: bindingUsage.aliases,
  }
}
